import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const GuiYeuCauBaoTri = () => {
    const now = new Date();
    const [selectedDate, setSelectedDate] = useState({
        d: now.getDate(),
        m: now.getMonth() + 1,
        y: now.getFullYear()
    });

    const [userRoom, setUserRoom] = useState('');
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [allRequests, setAllRequests] = useState([]);

    useEffect(() => {
        const profile = JSON.parse(localStorage.getItem('userProfile') || '{}');
        setUserRoom(profile.room_id || profile.room || 'Ẩn danh');
        loadData();
    }, [selectedDate]);

    const loadData = () => {
        const data = JSON.parse(localStorage.getItem('maintenance_data') || '[]');
        // Lọc dữ liệu theo ngày đã chọn để tất cả mọi người cùng xem
        const filtered = data.filter(item => 
            item.day === selectedDate.d && 
            item.month === selectedDate.m && 
            item.year === selectedDate.y
        );
        setAllRequests(filtered);
    };

    const handleSubmit = () => {
        if (!title || !description) return alert("Vui lòng nhập đủ thông tin!");

        const newRequest = {
            id: Date.now(),
            room: userRoom,
            title: title,
            issue: description, // Mô tả chi tiết
            status: 'pending',
            day: selectedDate.d,
            month: selectedDate.m,
            year: selectedDate.y,
            fullDate: `${selectedDate.d}/${selectedDate.m}/${selectedDate.y}`,
            createdAt: new Date().toLocaleTimeString()
        };

        const existingData = JSON.parse(localStorage.getItem('maintenance_data') || '[]');
        const updatedData = [newRequest, ...existingData];
        localStorage.setItem('maintenance_data', JSON.stringify(updatedData));

        setTitle('');
        setDescription('');
        loadData(); // Load lại danh sách để hiện yêu cầu vừa gửi
        alert("Đã gửi yêu cầu thành công!");
    };

    return (
        <div style={containerStyle}>
            {/* Header Chọn Ngày */}
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0 }}>🛠 BẢO TRÌ TÒA NHÀ</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select onChange={(e) => setSelectedDate({...selectedDate, d: parseInt(e.target.value)})} value={selectedDate.d} style={selectStyle}>
                        {Array.from({length: 31}, (_, i) => <option key={i+1} value={i+1}>Ngày {i+1}</option>)}
                    </select>
                    <select onChange={(e) => setSelectedDate({...selectedDate, m: parseInt(e.target.value)})} value={selectedDate.m} style={selectStyle}>
                        {Array.from({length: 12}, (_, i) => <option key={i+1} value={i+1}>Tháng {i+1}</option>)}
                    </select>
                </div>
            </div>

            <div style={contentStyle}>
                {/* Form Gửi Yêu Cầu */}
                <div style={formCardStyle}>
                    <h3 style={{ color: '#8b5e5e', marginTop: 0 }}>Gửi yêu cầu mới</h3>
                    <input 
                        style={inputStyle} 
                        placeholder="Tiêu đề (VD: Hỏng bóng đèn...)" 
                        value={title}
                        onChange={(e) => setTitle(e.target.value)}
                    />
                    <textarea 
                        style={textareaStyle} 
                        placeholder="Mô tả cụ thể sự cố bạn gặp phải..." 
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                    />
                    <button onClick={handleSubmit} style={btnStyle}>GỬI BAN QUẢN LÝ</button>
                </div>

                {/* Danh sách xem chung */}
                <div style={listCardStyle}>
                    <h3 style={{ color: '#8b5e5e', marginTop: 0 }}>Yêu cầu trong ngày {selectedDate.d}/{selectedDate.m}</h3>
                    <div style={{ overflowY: 'auto', flex: 1 }} className="custom-scrollbar">
                        {allRequests.length > 0 ? allRequests.map(req => (
                            <div key={req.id} style={itemStyle}>
                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                    <strong style={{fontSize: '16px'}}>P.{req.room} - {req.title}</strong>
                                    <span style={statusBadge(req.status)}>{req.status === 'pending' ? 'Chờ' : (req.status === 'processing' ? 'Đang sửa' : 'Xong')}</span>
                                </div>
                                <p style={{ fontSize: '14px', color: '#666', margin: '8px 0' }}>{req.issue}</p>
                                <small style={{ color: '#999' }}>Gửi lúc: {req.createdAt}</small>
                            </div>
                        )) : <p style={{ textAlign: 'center', color: '#ccc', marginTop: '50px' }}>Chưa có thông báo nào.</p>}
                    </div>
                </div>
            </div>
        </div>
    );
};

// Styles
const containerStyle = { flex: 1, display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', borderRadius: '30px', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const headerStyle = { padding: '20px 30px', background: 'rgba(0,0,0,0.4)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' };
const contentStyle = { flex: 1, display: 'flex', gap: '20px', padding: '20px', minHeight: 0 };
const formCardStyle = { width: '350px', background: '#fff', borderRadius: '20px', padding: '25px', display: 'flex', flexDirection: 'column', boxShadow: '0 10px 30px rgba(0,0,0,0.2)' };
const listCardStyle = { flex: 1, background: 'rgba(255,255,255,0.9)', borderRadius: '20px', padding: '25px', display: 'flex', flexDirection: 'column', boxShadow: '0 10px 30px rgba(0,0,0,0.2)' };
const inputStyle = { width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid #ddd', marginBottom: '15px', boxSizing: 'border-box' };
const textareaStyle = { ...inputStyle, height: '120px', resize: 'none' };
const btnStyle = { padding: '15px', borderRadius: '12px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', cursor: 'pointer' };
const selectStyle = { padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold' };
const itemStyle = { padding: '15px', background: '#fff', borderRadius: '15px', marginBottom: '10px', borderLeft: '5px solid #8b5e5e' };
const statusBadge = (s) => ({
    fontSize: '11px', padding: '3px 8px', borderRadius: '8px', fontWeight: 'bold',
    backgroundColor: s === 'pending' ? '#ffebeb' : (s === 'processing' ? '#fff9db' : '#ebffef'),
    color: s === 'pending' ? '#e03131' : (s === 'processing' ? '#f08c00' : '#2f9e44')
});

export default GuiYeuCauBaoTri;
